import ast, json, pathlib
roots = [pathlib.Path('src'), pathlib.Path('services'), pathlib.Path('scripts'), pathlib.Path('docker/mcp-servers-source'), pathlib.Path('docker/mcp-servers')]
rows=[]
for root in roots:
    if not root.exists():
        continue
    for path in root.rglob('*.py'):
        try:
            tree=ast.parse(path.read_text(errors='ignore'))
        except Exception as e:
            rows.append({'path': str(path), 'parse_error': type(e).__name__})
            continue
        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                decorators=[]
                for d in node.decorator_list:
                    try:
                        decorators.append(ast.unparse(d))
                    except Exception:
                        decorators.append(type(d).__name__)
                if decorators or node.name.startswith(('pm_', 'memory_', 'conport_', 'route_', 'handle_', 'get_', 'post_', 'put_', 'patch_', 'delete_')):
                    rows.append({'path': str(path), 'name': node.name, 'async': isinstance(node, ast.AsyncFunctionDef), 'decorators': decorators, 'lineno': node.lineno})
print(json.dumps(rows, indent=2, sort_keys=True))
